const $=(s,c=document)=>c.querySelector(s),$$=(s,c=document)=>[...c.querySelectorAll(s)];
const menu=$('.menu-toggle'),nav=$('.main-nav');
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')==='true';menu.setAttribute('aria-expanded',String(!open));nav.classList.toggle('open',!open)});
$$('.main-nav a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}));
const header=$('.site-header');
const syncHeader=()=>header.classList.toggle('scrolled',window.scrollY>36);
addEventListener('scroll',syncHeader,{passive:true});syncHeader();
addEventListener('keydown',e=>{if(e.key==='Escape'){nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}});
const toast=$('#toast');function notify(message){toast.textContent=message;toast.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>toast.classList.remove('show'),3600)}
$('#property-search-form').addEventListener('submit',e=>{e.preventDefault();$('#search-status').textContent='Recherche préparée. Tommy confirmera les propriétés actuellement disponibles selon vos critères.';document.querySelector('#proprietes').scrollIntoView({behavior:'smooth'});});
const evalForm=$('#evaluation-form'),step1=$('[data-step="1"]',evalForm),step2=$('[data-step="2"]',evalForm);
$('.next-step',evalForm).addEventListener('click',()=>{const required=$$('input[required],select[required]',step1);if(!required.every(i=>i.reportValidity()))return;step1.hidden=true;step1.classList.remove('active');step2.hidden=false;step2.classList.add('active');step2.scrollIntoView({behavior:'smooth',block:'center'})});
$('.back-step',evalForm).addEventListener('click',()=>{step2.hidden=true;step1.hidden=false;step1.scrollIntoView({behavior:'smooth',block:'center'})});
function handleDemoForm(form,message){form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const status=$('.form-status',form);status.textContent=message;notify(message);form.reset()})}
handleDemoForm(evalForm,'Merci! Votre demande est prête. La connexion au système de suivi sera la prochaine étape.');
handleDemoForm($('#alert-form'),'Vos critères sont prêts. La connexion au service d’alertes sera la prochaine étape.');
handleDemoForm($('#callback-form'),'Merci! Votre demande est prête à être transmise dès la connexion du formulaire.');
function calculateMortgage(){const p=Number($('#mortgage-price').value)||0,d=Number($('#mortgage-down').value)||0,annual=(Number($('#mortgage-rate').value)||0)/100,years=Number($('#mortgage-years').value)||25;let principal=Math.max(0,p-d),insurance=0;if(p>0&&d/p<.2){const ratio=d/p;const factor=ratio<.1?.04:ratio<.15?.031: .028;insurance=principal*factor;principal+=insurance}const r=annual/12,n=years*12;const payment=r?principal*(r*Math.pow(1+r,n))/(Math.pow(1+r,n)-1):principal/n;$('#mortgage-result').textContent=payment.toLocaleString('fr-CA',{style:'currency',currency:'CAD',maximumFractionDigits:0});$('#insurance-note').textContent=insurance?`Inclut une prime d’assurance hypothécaire estimée à ${insurance.toLocaleString('fr-CA',{style:'currency',currency:'CAD',maximumFractionDigits:0})}.`:'Aucune prime d’assurance hypothécaire estimée.'}
['#mortgage-price','#mortgage-down','#mortgage-rate','#mortgage-years'].forEach(s=>$(s).addEventListener('input',calculateMortgage));calculateMortgage();
const reveal=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('revealed');reveal.unobserve(entry.target)}}),{threshold:.08});$$('section:not(.hero),.footer').forEach(el=>{el.style.opacity='0';el.style.transform='translateY(18px)';el.style.transition='opacity .65s ease, transform .65s ease';reveal.observe(el)});document.head.insertAdjacentHTML('beforeend','<style>.revealed{opacity:1!important;transform:none!important}@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important;transition:none!important}}</style>');
if(matchMedia('(pointer:fine) and (prefers-reduced-motion:no-preference)').matches){const hero=$('.hero'),backdrop=$('.hero-backdrop'),portrait=$('.hero-portrait');hero.addEventListener('pointermove',e=>{const x=(e.clientX/window.innerWidth-.5),y=(e.clientY/window.innerHeight-.5);backdrop.style.transform=`scale(1.035) translate(${x*-7}px,${y*-5}px)`;portrait.style.translate=`${x*-7}px ${y*-6}px`});hero.addEventListener('pointerleave',()=>{backdrop.style.transform='scale(1.02)';portrait.style.translate='0 0'})}
